-- READ ONLY. No Auth rows, passwords, JWTs, sessions, or Storage objects are returned.
with schemas(name) as (values('public'),('private'),('meal_history'),('attendance_backup'),('recruitment_private'),('sm_history'),('sm_private')),
rel as(select c.*,n.nspname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in(select name from schemas) and c.relkind in('r','p','v')),
fn as(select p.*,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in(select name from schemas))
select jsonb_build_object(
 'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'acl',nspacl::text) order by nspname) from pg_namespace where nspname in(select name from schemas)),
 'relations',(select jsonb_agg(jsonb_build_object('schema',nspname,'name',relname,'kind',relkind,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'options',reloptions,'acl',relacl::text,'view',case when relkind='v' then pg_get_viewdef(oid,true) end) order by nspname,relname) from rel),
 'columns',(select jsonb_agg(jsonb_build_object('schema',r.nspname,'table',r.relname,'name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) order by r.nspname,r.relname,a.attnum) from rel r join pg_attribute a on a.attrelid=r.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum),
 'constraints',(select jsonb_agg(jsonb_build_object('schema',r.nspname,'table',r.relname,'name',c.conname,'type',c.contype,'def',pg_get_constraintdef(c.oid),'validated',c.convalidated,'ref_schema',rn.nspname,'ref_table',rc.relname,'columns',(select jsonb_agg(attname order by ord) from unnest(c.conkey) with ordinality u(num,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=u.num)) order by r.nspname,r.relname,c.conname) from pg_constraint c join rel r on r.oid=c.conrelid left join pg_class rc on rc.oid=c.confrelid left join pg_namespace rn on rn.oid=rc.relnamespace),
 'indexes',(select jsonb_agg(to_jsonb(i) order by schemaname,tablename,indexname) from pg_indexes i where schemaname in(select name from schemas)),
 'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in(select name from schemas)),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',r.nspname,'table',r.relname,'name',t.tgname,'def',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by r.nspname,r.relname,t.tgname) from pg_trigger t join rel r on r.oid=t.tgrelid where not t.tgisinternal),
 'functions',(select jsonb_agg(jsonb_build_object('schema',nspname,'name',proname,'identity',pg_get_function_identity_arguments(oid),'def',pg_get_functiondef(oid),'definer',prosecdef,'config',proconfig,'acl',proacl::text) order by nspname,proname,oid) from fn),
 'sequences',(select jsonb_agg(to_jsonb(s)||jsonb_build_object('max_value',max_value::text,'min_value',min_value::text,'last_value',last_value::text,'start_value',start_value::text,'increment_by',increment_by::text,'cache_size',cache_size::text) order by schemaname,sequencename) from pg_sequences s where schemaname in(select name from schemas)),
 'types',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'labels',(select jsonb_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in(select name from schemas) and t.typtype in('e','d')),
 'version',version()
) as metadata;
